            missing,
            capability,
            spec,
            hostCapabilityTransports[capability]!.defaults,
          );
          entries.add(
            WiredCapability(
              capability,
              hostCapabilityTransports[capability]!.defaults,
            ),
          );
        case CapabilityTransportState(:final transports):
          _requireServices(missing, capability, spec, transports);
          entries.add(WiredCapability(capability, transports));
