    sandboxEnv = SandboxedExecutionEnv(
      env,
      sandbox.spec,
      homeDir: sandbox.homeDir,
      workspaceRoot: env.cwd,
      pathProbe: sandbox.pathProbe,
      os: sandbox.os,
      onWarning: sandbox.onWarning,
    );
    env = sandboxEnv;
  }
  final sessionVars = services.sessionEnvVars;
